  sum += texture2D(tDiffuse, vUv + vec2(0.0, uTexelSize.y * 1.3846)).rgb * 0.316216;
  sum += texture2D(tDiffuse, vUv - vec2(0.0, uTexelSize.y * 1.3846)).rgb * 0.316216;
